CREATE TABLE customers(customer_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE,phone VARCHAR(20) UNIQUE,loyalty_points INTEGER NOT NULL DEFAULT 0 CHECK(loyalty_points>=0));
CREATE TABLE employees(employee_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,role VARCHAR(50) NOT NULL CHECK(role IN('Barista','Manager','Cashier','Chef','Server')),hire_date DATE NOT NULL);
CREATE TABLE menu_items(menu_item_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,category VARCHAR(50) NOT NULL,price NUMERIC(10,2) NOT NULL CHECK(price>=0),status VARCHAR(20) NOT NULL DEFAULT 'Available' CHECK(status IN('Available','Out of Stock')));
CREATE TABLE orders(order_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_datetime TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,customer_id INTEGER REFERENCES customers(customer_id) ON DELETE SET NULL,employee_id INTEGER NOT NULL REFERENCES employees(employee_id) ON DELETE RESTRICT,total_amount NUMERIC(12,2) NOT NULL CHECK(total_amount>=0));
CREATE TABLE order_items(order_item_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,menu_item_id INTEGER NOT NULL REFERENCES menu_items(menu_item_id) ON DELETE RESTRICT,quantity INTEGER NOT NULL CHECK(quantity>0),subtotal NUMERIC(12,2) NOT NULL CHECK(subtotal>=0),UNIQUE(order_id,menu_item_id));
CREATE TABLE inventory(inventory_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,item_name VARCHAR(100) NOT NULL UNIQUE,current_stock NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK(current_stock>=0),minimum_stock_level NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK(minimum_stock_level>=0));
